       fair_date_id
     , price
     , capacity
     , status
     , updated_by
     , version
     , created_at
     , updated_at
) VALUES (
       #{fairDateId}
     , #{price}
     , #{capacity}
     , #{status}
     , #{updatedBy}
     , 0
     , #{now}
     , #{now}
)

mapper.update:
UPDATE onsite_sales_policies
   SET price = #{price}
     , capacity = #{capacity}
     , status = #{status}
     , updated_by = #{updatedBy}
     , version = version + 1
     , updated_at = #{now}
 WHERE fair_date_id = #{fairDateId}
   AND version = #{expectedVersion}
